import{}from"viem";import{writeContract}from"viem/actions";import{getAction}from"viem/utils";import{SessionKeyValidatorAbi}from"../abis/SessionKeyValidator.js";import{SESSION_KEY_VALIDATOR_ADDRESS}from"../constants.js";import{getSessionHash}from"../sessions.js";export async function revokeSessions(client,args){const{session,...rest}=args,sessionHashes="string"==typeof session?[session]:Array.isArray(session)?session.map(sessionHash):[getSessionHash(session)];return{transactionHash:await getAction(client,writeContract,"writeContract")({address:SESSION_KEY_VALIDATOR_ADDRESS,abi:SessionKeyValidatorAbi,functionName:"revokeKeys",args:[sessionHashes],...rest})}}function sessionHash(session){return"string"==typeof session?session:getSessionHash(session)}