import{estimateGas as viem_estimateGas}from"viem/actions";import{getAction}from"../utils/getAction.js";import{getConnectorClient}from"./getConnectorClient.js";export async function estimateGas(config,parameters){const{chainId,connector,...rest}=parameters;let account;if(parameters.account)account=parameters.account;else{account=(await getConnectorClient(config,{account:parameters.account,chainId,connector})).account}const client=config.getClient({chainId});return getAction(client,viem_estimateGas,"estimateGas")({...rest,account})}