import{createClient,createPublicClient,createWalletClient,http}from"viem";import{toAccount}from"viem/accounts";import{}from"viem/zksync";import{getSmartAccountAddressFromInitialSigner}from"./utils.js";import{globalWalletActions}from"./walletActions.js";export async function createAbstractClient({signer,chain,transport,address,isPrivyCrossApp=!1,publicTransport=http(void 0,{batch:!0}),customPaymasterHandler}){if(!transport)throw new Error("Transport is required");const publicClient=createPublicClient({chain,transport:publicTransport}),smartAccountAddress=address??await getSmartAccountAddressFromInitialSigner(signer.address,publicClient),baseClient=createClient({account:toAccount(smartAccountAddress),chain,transport}),signerWalletClient=createWalletClient({account:signer,chain,transport});return baseClient.extend(globalWalletActions(signerWalletClient,publicClient,isPrivyCrossApp,customPaymasterHandler))}