import{getCallsStatus as viem_getCallsStatus}from"viem/actions";import{getAction}from"../utils/getAction.js";import{getConnectorClient}from"./getConnectorClient.js";export async function getCallsStatus(config,parameters){const{connector,id}=parameters,client=await getConnectorClient(config,{connector});return getAction(client,viem_getCallsStatus,"getCallsStatus")({id})}