import{simulateContract as viem_simulateContract}from"viem/actions";import{getAction}from"../utils/getAction.js";import{getConnectorClient}from"./getConnectorClient.js";export async function simulateContract(config,parameters){const{abi,chainId,connector,...rest}=parameters;let account;if(parameters.account)account=parameters.account;else{account=(await getConnectorClient(config,{chainId,connector})).account}const client=config.getClient({chainId}),action=getAction(client,viem_simulateContract,"simulateContract"),{result,request}=await action({...rest,abi,account});return{chainId:client.chain.id,result,request:{...request,chainId}}}