import{getFeeHistoryQueryOptions}from"@wagmi/core/query";import{useQuery}from"../utils/query.js";import{useChainId}from"./useChainId.js";import{useConfig}from"./useConfig.js";export function useFeeHistory(parameters={}){const{blockCount,rewardPercentiles,query={}}=parameters,config=useConfig(parameters),chainId=useChainId({config}),options=getFeeHistoryQueryOptions(config,{...parameters,chainId:parameters.chainId??chainId}),enabled=Boolean(blockCount&&rewardPercentiles&&(query.enabled??!0));return useQuery({...query,...options,enabled})}