export function getDecayedAmount(config,atTime=Math.floor(Date.now()/1e3)){const{startAmount,endAmount,decayStartTime,decayEndTime}=config;if(decayEndTime<=atTime)return endAmount;if(decayStartTime>=atTime)return startAmount;if(startAmount.eq(endAmount))return startAmount;const duration=decayEndTime-decayStartTime,elapsed=atTime-decayStartTime;if(startAmount.gt(endAmount)){const decay=startAmount.sub(endAmount).mul(elapsed).div(duration);return startAmount.sub(decay)}{const decay=endAmount.sub(startAmount).mul(elapsed).div(duration);return startAmount.add(decay)}}