import{ethers}from"ethers";import{EXCLUSIVE_FILLER_VALIDATION_MAPPING}from"../constants";export var ValidationType;!function(ValidationType){ValidationType[ValidationType.None=0]="None",ValidationType[ValidationType.ExclusiveFiller=1]="ExclusiveFiller"}(ValidationType||(ValidationType={}));const NONE_VALIDATION={type:ValidationType.None,data:null};export function parseValidation(info){const data=parseExclusiveFillerData(info.additionalValidationData);return data.type!==ValidationType.None?data:NONE_VALIDATION}export function parseExclusiveFillerData(encoded){try{const[address,timestamp]=(new ethers.utils.AbiCoder).decode(["address","uint256"],encoded);return{type:ValidationType.ExclusiveFiller,data:{filler:address,lastExclusiveTimestamp:timestamp.toNumber()}}}catch(_a){return NONE_VALIDATION}}export function encodeExclusiveFillerData(fillerAddress,lastExclusiveTimestamp,chainId,additionalValidationContractAddress){let additionalValidationContract="";if(additionalValidationContractAddress)additionalValidationContract=additionalValidationContractAddress;else{if(!chainId)throw new Error("No validation contract provided");additionalValidationContract=EXCLUSIVE_FILLER_VALIDATION_MAPPING[chainId]}return{additionalValidationContract,additionalValidationData:(new ethers.utils.AbiCoder).encode(["address","uint256"],[fillerAddress,lastExclusiveTimestamp])}}