import{getConnections,watchConnections}from"@wagmi/core";import{useSyncExternalStore}from"react";import{useConfig}from"./useConfig.js";export function useConnections(parameters={}){const config=useConfig(parameters);return useSyncExternalStore(onChange=>watchConnections(config,{onChange}),()=>getConnections(config),()=>getConnections(config))}