import{}from"viem";import{}from"viem/zksync";import{signPrivyTransaction}from"./sendPrivyTransaction.js";import{getBatchTransactionObject}from"./sendTransactionBatch.js";import{signTransaction}from"./signTransaction.js";export async function signTransactionBatch(client,signerClient,publicClient,parameters,validator,validationHookData={},customPaymasterHandler=void 0,isPrivyCrossApp=!1){const{calls,...rest}=parameters;if(0===calls.length)throw new Error("No calls provided");if(isPrivyCrossApp)return await signPrivyTransaction(client,parameters);const batchTransaction=getBatchTransactionObject(client.account.address,parameters);return signTransaction(client,signerClient,publicClient,{...batchTransaction,...rest},validator,validationHookData,customPaymasterHandler)}