import{ChainDisconnectedError,createTransport,hexToNumber,ProviderDisconnectedError,withRetry,withTimeout}from"viem";export function unstable_connector(connector,config={}){const{type}=connector,{key="connector",name="Connector",retryDelay}=config;return parameters=>{const{chain,connectors}=parameters,retryCount=config.retryCount??parameters.retryCount;return createTransport({key,name,request:async({method,params})=>{const connector=connectors?.getState().find(c=>c.type===type);if(!connector)throw new ProviderDisconnectedError(new Error(`Could not find connector of type "${type}" in \`connectors\` passed to \`createConfig\`.`));const provider=await connector.getProvider({chainId:chain?.id});if(!provider)throw new ProviderDisconnectedError(new Error("Provider is disconnected."));const chainId=hexToNumber(await withRetry(()=>withTimeout(()=>provider.request({method:"eth_chainId"}),{timeout:100})));if(chain&&chainId!==chain.id)throw new ChainDisconnectedError(new Error(`The current chain of the connector (id: ${chainId}) does not match the target chain for the request (id: ${chain.id} – ${chain.name}).`));const body={method,params};return provider.request(body)},retryCount,retryDelay,type:"connector"})}}