import{getTransactionReceiptQueryOptions}from"@wagmi/core/query";import{useQuery}from"../utils/query.js";import{useChainId}from"./useChainId.js";import{useConfig}from"./useConfig.js";export function useTransactionReceipt(parameters={}){const{hash,query={}}=parameters,config=useConfig(parameters),chainId=useChainId({config}),options=getTransactionReceiptQueryOptions(config,{...parameters,chainId:parameters.chainId??chainId}),enabled=Boolean(hash&&(query.enabled??!0));return useQuery({...query,...options,enabled})}