import{getClient,watchClient}from"@wagmi/core";import{useSyncExternalStoreWithSelector}from"use-sync-external-store/shim/with-selector.js";import{useConfig}from"./useConfig.js";export function useClient(parameters={}){const config=useConfig(parameters);return useSyncExternalStoreWithSelector(onChange=>watchClient(config,{onChange}),()=>getClient(config,parameters),()=>getClient(config,parameters),x=>x,(a,b)=>a?.uid===b?.uid)}