import{getBlock as viem_getBlock}from"viem/actions";import{getAction}from"../utils/getAction.js";export async function getBlock(config,parameters={}){const{chainId,...rest}=parameters,client=config.getClient({chainId}),action=getAction(client,viem_getBlock,"getBlock");return{...await action(rest),chainId:client.chain.id}}