import{encodeAbiParameters,encodeFunctionData,keccak256,parseAbiParameters,serializeErc6492Signature,toBytes,zeroAddress}from"viem";import{getCode,signTypedData}from"viem/actions";import AccountFactoryAbi from"./abis/AccountFactory.js";import{EOA_VALIDATOR_ADDRESS,SMART_ACCOUNT_FACTORY_ADDRESS}from"./constants.js";import{getInitializerCalldata}from"./utils.js";export async function getAgwTypedSignature(args){const{client,signer,messageHash}=args,chainId=client.chain.id,account=client.account,rawSignature=await signTypedData(signer,{domain:{name:"AbstractGlobalWallet",version:"1.0.0",chainId:BigInt(chainId),verifyingContract:account.address},types:{EIP712Domain:[{name:"name",type:"string"},{name:"version",type:"string"},{name:"chainId",type:"uint256"},{name:"verifyingContract",type:"address"}],AGWMessage:[{name:"signedHash",type:"bytes32"}]},message:{signedHash:messageHash},primaryType:"AGWMessage"}),signature=encodeAbiParameters(parseAbiParameters(["bytes","address"]),[rawSignature,EOA_VALIDATOR_ADDRESS]);if(void 0!==await getCode(client,{address:account.address}))return signature;const addressBytes=toBytes(signer.account.address),salt=keccak256(addressBytes);return serializeErc6492Signature({address:SMART_ACCOUNT_FACTORY_ADDRESS,data:encodeFunctionData({abi:AccountFactoryAbi,functionName:"deployAccount",args:[salt,getInitializerCalldata(signer.account.address,EOA_VALIDATOR_ADDRESS,{target:zeroAddress,allowFailure:!1,callData:"0x",value:0n})]}),signature})}