import{useMutation}from"@tanstack/react-query";import{disconnectMutationOptions}from"@wagmi/core/query";import{useConfig}from"./useConfig.js";import{useConnections}from"./useConnections.js";export function useDisconnect(parameters={}){const{mutation}=parameters,config=useConfig(parameters),mutationOptions=disconnectMutationOptions(config),{mutate,mutateAsync,...result}=useMutation({...mutation,...mutationOptions});return{...result,connectors:useConnections({config}).map(connection=>connection.connector),disconnect:mutate,disconnectAsync:mutateAsync}}