import{useMutation}from"@tanstack/react-query";import{showCallsStatusMutationOptions}from"@wagmi/core/query";import{useConfig}from"./useConfig.js";export function useShowCallsStatus(parameters={}){const{mutation}=parameters,config=useConfig(parameters),mutationOptions=showCallsStatusMutationOptions(config),{mutate,mutateAsync,...result}=useMutation({...mutation,...mutationOptions});return{...result,showCallsStatus:mutate,showCallsStatusAsync:mutateAsync}}