import{encodeFunctionData}from"viem";import{}from"viem/zksync";import AGWAccountAbi from"../abis/AGWAccount.js";import{EOA_VALIDATOR_ADDRESS}from"../constants.js";import{}from"../types/call.js";import{signPrivyTransaction}from"./sendPrivyTransaction.js";import{sendTransactionInternal}from"./sendTransactionInternal.js";export function getBatchTransactionObject(address,parameters){const{calls,paymaster,paymasterInput}=parameters,batchCalls=calls.map(tx=>{if(!tx.to)throw new Error("Transaction target (to) is required");return{target:tx.to,allowFailure:!1,value:BigInt(tx.value??0),callData:tx.data??"0x"}});return{to:address,data:encodeFunctionData({abi:AGWAccountAbi,functionName:"batchCall",args:[batchCalls]}),value:batchCalls.reduce((sum,call)=>sum+BigInt(call.value),BigInt(0)),paymaster,paymasterInput,type:"eip712"}}export async function sendTransactionBatch(client,signerClient,publicClient,parameters,isPrivyCrossApp=!1,customPaymasterHandler=void 0){const{calls,...rest}=parameters;if(0===calls.length)throw new Error("No calls provided");if(isPrivyCrossApp){const signedTx=await signPrivyTransaction(client,parameters);return await publicClient.sendRawTransaction({serializedTransaction:signedTx})}const batchTransaction=getBatchTransactionObject(client.account.address,parameters);return sendTransactionInternal(client,signerClient,publicClient,{...batchTransaction,...rest},EOA_VALIDATOR_ADDRESS,{},customPaymasterHandler)}