import{signTypedData as viem_signTypedData}from"viem/actions";import{getAction}from"../utils/getAction.js";import{getConnectorClient}from"./getConnectorClient.js";export async function signTypedData(config,parameters){const{account,connector,...rest}=parameters;let client;client="object"==typeof account&&"local"===account.type?config.getClient():await getConnectorClient(config,{account,connector});return getAction(client,viem_signTypedData,"signTypedData")({...rest,...account?{account}:{}})}