import{ethers}from"ethers";import{OrderType,REVERSE_REACTOR_MAPPING}from"../constants";import{MissingConfiguration}from"../errors";import{CosignedPriorityOrder,CosignedV2DutchOrder,DutchOrder,RelayOrder,UnsignedPriorityOrder,UnsignedV2DutchOrder}from"../order";import{CosignedV3DutchOrder,UnsignedV3DutchOrder}from"../order/V3DutchOrder";import{stripHexPrefix}from".";const UNISWAPX_ORDER_INFO_OFFSET=64,RELAY_ORDER_INFO_OFFSET=64,SLOT_LENGTH=64,ADDRESS_LENGTH=40;class OrderParser{_parseOrder(order){const strippedOrder=stripHexPrefix(order),reactorAddressOffset=2*parseInt(strippedOrder.slice(this.orderInfoOffset,this.orderInfoOffset+64),16)+64,reactorAddressSlot=strippedOrder.slice(reactorAddressOffset,reactorAddressOffset+64),reactorAddress=ethers.utils.getAddress(reactorAddressSlot.slice(24)).toLowerCase();if(!REVERSE_REACTOR_MAPPING[reactorAddress])throw new MissingConfiguration("reactor",reactorAddress);return REVERSE_REACTOR_MAPPING[reactorAddress].orderType}getOrderType(order){const{orderType}=REVERSE_REACTOR_MAPPING[order.info.reactor.toLowerCase()];return orderType}getOrderTypeFromEncoded(order,chainId){const parsedOrder=this.parseOrder(order,chainId);return this.getOrderType(parsedOrder)}}export class UniswapXOrderParser extends OrderParser{constructor(){super(...arguments),this.orderInfoOffset=64}parseOrder(order,chainId){const orderType=this._parseOrder(order);switch(orderType){case OrderType.Dutch:return DutchOrder.parse(order,chainId);case OrderType.Dutch_V2:{const cosignedOrder=CosignedV2DutchOrder.parse(order,chainId);return"0x"===cosignedOrder.info.cosignature?UnsignedV2DutchOrder.parse(order,chainId):cosignedOrder}case OrderType.Dutch_V3:{const cosignedOrder=CosignedV3DutchOrder.parse(order,chainId);return"0x"===cosignedOrder.info.cosignature?UnsignedV3DutchOrder.parse(order,chainId):cosignedOrder}case OrderType.Priority:{const cosignedOrder=CosignedPriorityOrder.parse(order,chainId);return"0x"===cosignedOrder.info.cosignature?UnsignedPriorityOrder.parse(order,chainId):cosignedOrder}default:throw new MissingConfiguration("orderType",orderType)}}getOrderType(order){const{orderType}=REVERSE_REACTOR_MAPPING[order.info.reactor.toLowerCase()];if(orderType==OrderType.Dutch){const input=order.info.input,outputs=order.info.outputs;return input.startAmount.eq(input.endAmount)&&outputs.every(output=>output.startAmount.eq(output.endAmount))?OrderType.Limit:OrderType.Dutch}return orderType}}export class RelayOrderParser extends OrderParser{constructor(){super(...arguments),this.orderInfoOffset=64}parseOrder(order,chainId){return RelayOrder.parse(order,chainId)}}export function originalIfZero(value,original){return value.isZero()?original:value}