import{getProofQueryOptions}from"@wagmi/core/query";import{useQuery}from"../utils/query.js";import{useChainId}from"./useChainId.js";import{useConfig}from"./useConfig.js";export function useProof(parameters={}){const{address,storageKeys,query={}}=parameters,config=useConfig(parameters),chainId=useChainId({config}),options=getProofQueryOptions(config,{...parameters,chainId:parameters.chainId??chainId}),enabled=Boolean(address&&storageKeys&&(query.enabled??!0));return useQuery({...query,...options,enabled})}