import{getChainId,watchChainId}from"@wagmi/core";import{useSyncExternalStore}from"react";import{useConfig}from"./useConfig.js";export function useChainId(parameters={}){const config=useConfig(parameters);return useSyncExternalStore(onChange=>watchChainId(config,{onChange}),()=>getChainId(config),()=>getChainId(config))}