import{getCapabilities as viem_getCapabilities}from"viem/experimental";import{getConnectorClient}from"../../actions/getConnectorClient.js";import{}from"../../createConfig.js";export async function getCapabilities(config,parameters={}){const{account,connector}=parameters,client=await getConnectorClient(config,{account,connector});return viem_getCapabilities(client,{account})}