import{jsx as _jsx}from"react/jsx-runtime";import{ConnectError}from"@connectrpc/connect";import{createContext,useContext}from"react";const fallbackTransportError=new ConnectError("To use Connect, you must provide a `Transport`: a simple object that handles `unary` and `stream` requests. `Transport` objects can easily be created by using `@connectrpc/connect-web`'s exports `createConnectTransport` and `createGrpcWebTransport`. see: https://connectrpc.com/docs/web/getting-started for more info.");export const fallbackTransport={unary:()=>{throw fallbackTransportError},stream:()=>{throw fallbackTransportError}};const transportContext=createContext(fallbackTransport);export const useTransport=()=>useContext(transportContext);export const TransportProvider=({children,transport})=>_jsx(transportContext.Provider,{value:transport,children});