import{writeContract as viem_writeContract}from"viem/actions";import{}from"../createConfig.js";import{}from"../errors/base.js";import{}from"../types/chain.js";import{}from"../types/properties.js";import{getAction}from"../utils/getAction.js";import{getAccount}from"./getAccount.js";import{getConnectorClient}from"./getConnectorClient.js";import{simulateContract}from"./simulateContract.js";export async function writeContract(config,parameters){const{account,chainId,connector,__mode,...rest}=parameters;let client;client="object"==typeof account&&"local"===account.type?config.getClient({chainId}):await getConnectorClient(config,{account,chainId,connector});const{connector:activeConnector}=getAccount(config);let request;if("prepared"===__mode||activeConnector?.supportsSimulation)request=rest;else{const{request:simulateRequest}=await simulateContract(config,{...rest,account,chainId});request=simulateRequest}const action=getAction(client,viem_writeContract,"writeContract");return await action({...request,...account?{account}:{},chain:chainId?{id:chainId}:null})}