import{getTransactionReceipt as viem_getTransactionReceipt}from"viem/actions";import{getAction}from"../utils/getAction.js";export async function getTransactionReceipt(config,parameters){const{chainId,...rest}=parameters,client=config.getClient({chainId});return getAction(client,viem_getTransactionReceipt,"getTransactionReceipt")(rest)}