import{getEnsResolverQueryOptions}from"@wagmi/core/query";import{useQuery}from"../utils/query.js";import{useChainId}from"./useChainId.js";import{useConfig}from"./useConfig.js";export function useEnsResolver(parameters={}){const{name,query={}}=parameters,config=useConfig(parameters),chainId=useChainId({config}),options=getEnsResolverQueryOptions(config,{...parameters,chainId:parameters.chainId??chainId}),enabled=Boolean(name&&(query.enabled??!0));return useQuery({...query,...options,enabled})}