import{toHex}from"viem";import{}from"viem/zksync";import{replaceBigInts}from"../replaceBigInts.js";export async function sendPrivyTransaction(client,parameters){return await client.request({method:"privy_sendSmartWalletTx",params:[replaceBigInts(parameters,toHex)]},{retryCount:0})}export async function sendPrivySignMessage(client,parameters){return await client.request({method:"privy_signSmartWalletMessage",params:[parameters.message]},{retryCount:0})}export async function sendPrivySignTypedData(client,parameters){return await client.request({method:"privy_signSmartWalletTypedData",params:[client.account.address,parameters]},{retryCount:0})}export async function signPrivyTransaction(client,parameters){const{chain:_chain,account:_account,...request}=parameters;return await client.request({method:"privy_signSmartWalletTx",params:[replaceBigInts(request,toHex)]},{retryCount:0})}