import{headerProtocolVersion}from"./headers.js";import{paramConnectVersion}from"./query-params.js";import{ConnectError}from"../connect-error.js";import{Code}from"../code.js";export const protocolVersion="1";export function requireProtocolVersionHeader(requestHeader){const v=requestHeader.get(headerProtocolVersion);if(null===v)throw new ConnectError(`missing required header: set ${headerProtocolVersion} to "1"`,Code.InvalidArgument);if("1"!==v)throw new ConnectError(`${headerProtocolVersion} must be "1": got "${v}"`,Code.InvalidArgument)}export function requireProtocolVersionParam(queryParams){const v=queryParams.get(paramConnectVersion);if(null===v)throw new ConnectError(`missing required parameter: set ${paramConnectVersion} to "v1"`,Code.InvalidArgument);if("v1"!==v)throw new ConnectError(`${paramConnectVersion} must be "v1": got "${v}"`,Code.InvalidArgument)}